package com.example.jobfinderapp.adapters;
import android.view.*;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.jobfinderapp.R;import java.util.*;
public class ManageUsersAdapter extends RecyclerView.Adapter<ManageUsersAdapter.H>{public interface L{void click(Map<String,Object> row);}private final List<Map<String,Object>> data;private final L listener;public ManageUsersAdapter(List<Map<String,Object>> data,L listener){this.data=data;this.listener=listener;}@NonNull public H onCreateViewHolder(@NonNull ViewGroup p,int t){return new H(LayoutInflater.from(p.getContext()).inflate(R.layout.item_manage_user,p,false));}public void onBindViewHolder(@NonNull H h,int i){Map<String,Object>r=data.get(i);h.name.setText(String.valueOf(r.get("fullname")));h.info.setText(String.valueOf(r.get("email"))+"\n"+String.valueOf(r.get("role"))+" · "+String.valueOf(r.get("status")));h.itemView.setOnClickListener(v->listener.click(r));}public int getItemCount(){return data.size();}static class H extends RecyclerView.ViewHolder{TextView name,info;H(View v){super(v);name=v.findViewById(R.id.tvUserName);info=v.findViewById(R.id.tvUserInfo);}}}
